/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: catalogFile
 * Internal
 *   Functions: syntaxFor, wrapList, unique, titleOf, collectTests, isFunctionLike, hasExport,
 *              topLevelStatements, codeCatalog, cssCatalog, shellCatalog, pythonCatalog, yamlCatalog,
 *              anchorFactory, markdownLines, markdownCatalog, catalogLines, stripCatalog, insertCatalog,
 *              renderBlock, candidateFiles, main
 *   Constants: repositoryRoot, lineThreshold, wrapWidth, generatorCommand, excluded, markers, testCallee
 * @end-catalog */

import { execFileSync } from 'node:child_process';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import ts from 'typescript';

/**
 * Keeps a generated catalog at the top of every hand-written source or document
 * file longer than the threshold, so a reader can see what a long file contains
 * before scrolling. `--check` fails when any catalog is missing or stale.
 */
const repositoryRoot = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const lineThreshold = 100;
const wrapWidth = 110;
const generatorCommand = 'npm run catalog:generate';

/** Vendored, generated, fixture, and license files are not authored here and keep their upstream form. */
const excluded = [
  /(^|\/)node_modules\//,
  /^localization\/generated\//,
  /^src\/public\/fonts\//,
  /^web\/public\/licenses\//,
  /(^|\/)fixtures\//,
  /\.d\.m?ts$/,
  /(^|\/)LICENSE/
];

const syntaxFor = file => {
  if (/\.(ts|tsx|mts|cts|js|mjs|cjs|jsx)$/.test(file)) return 'code';
  if (/\.css$/.test(file)) return 'css';
  if (/\.md$/.test(file)) return 'markdown';
  if (/\.sh$/.test(file)) return 'shell';
  if (/\.py$/.test(file)) return 'python';
  if (/\.ya?ml$/.test(file)) return 'yaml';
  return null;
};

/** Each syntax stores its catalog between recognizable start and end lines. */
const markers = {
  code: { start: '/* @catalog', end: ' * @end-catalog */', line: text => ` *${text ? ` ${text}` : ''}` },
  css: { start: '/* @catalog', end: ' * @end-catalog */', line: text => ` *${text ? ` ${text}` : ''}` },
  shell: { start: '# @catalog', end: '# @end-catalog', line: text => `#${text ? ` ${text}` : ''}` },
  python: { start: '# @catalog', end: '# @end-catalog', line: text => `#${text ? ` ${text}` : ''}` },
  yaml: { start: '# @catalog', end: '# @end-catalog', line: text => `#${text ? ` ${text}` : ''}` },
  markdown: { start: '<!-- @catalog -->', end: '<!-- @end-catalog -->', line: text => text }
};

/** Wraps a labelled, comma-separated list into continuation lines indented under the label. */
const wrapList = (label, values, indent = '', separator = ',') => {
  if (!values.length) return [];
  const lines = [];
  let current = `${indent}${label}: `;
  const continuation = `${indent}${' '.repeat(label.length + 2)}`;
  values.forEach((value, index) => {
    const piece = `${value}${index < values.length - 1 ? separator : ''}`;
    if (current.trim().length > label.length + 1 && current.length + piece.length + 1 > wrapWidth) {
      lines.push(current.trimEnd());
      current = continuation;
    }
    current += `${piece} `;
  });
  lines.push(current.trimEnd());
  return lines;
};

const unique = values => [...new Set(values)];

const testCallee = /^(test|it|describe|suite)(\.(describe|skip|only|serial|parallel|fixme|concurrent|todo|sequential))*$/;

/** Reads a test title from a string, a template literal, or any other expression's source text. */
const titleOf = (node, source) => {
  if (!node) return null;
  if (ts.isStringLiteralLike(node)) return node.text;
  if (ts.isTemplateExpression(node)) return node.getText(source).slice(1, -1);
  return node.getText(source);
};

/** Collects describe/test titles, nesting describe blocks by indentation. */
const collectTests = (statements, source, depth = 0, output = []) => {
  for (const statement of statements) {
    if (!ts.isExpressionStatement(statement) || !ts.isCallExpression(statement.expression)) continue;
    const call = statement.expression;
    const callee = call.expression.getText(source);
    if (!testCallee.test(callee)) continue;
    const title = titleOf(call.arguments[0], source);
    if (title === null) continue;
    output.push(`${'  '.repeat(depth)}- ${title.replace(/\s+/g, ' ')}`);
    if (/describe|suite/.test(callee)) {
      const body = call.arguments.find(argument => ts.isArrowFunction(argument) || ts.isFunctionExpression(argument));
      if (body && ts.isBlock(body.body)) collectTests(body.body.statements, source, depth + 1, output);
    }
  }
  return output;
};

const isFunctionLike = node => !!node && (ts.isArrowFunction(node) || ts.isFunctionExpression(node));
const hasExport = node => ts.canHaveModifiers(node)
  && (ts.getModifiers(node) ?? []).some(modifier => modifier.kind === ts.SyntaxKind.ExportKeyword);

/** Browser scripts wrap their module scope in an IIFE; its body counts as top level. */
const topLevelStatements = statements => statements.flatMap(statement => {
  if (!ts.isExpressionStatement(statement) || !ts.isCallExpression(statement.expression)) return [statement];
  let callee = statement.expression.expression;
  while (ts.isParenthesizedExpression(callee)) callee = callee.expression;
  return isFunctionLike(callee) && ts.isBlock(callee.body) ? topLevelStatements(callee.body.statements) : [statement];
});

/** Lists top-level declarations by visibility and kind, plus test titles in test files. */
const codeCatalog = (file, content) => {
  const kind = file.endsWith('.tsx') || file.endsWith('.jsx') ? ts.ScriptKind.TSX
    : /\.(m|c)?js$/.test(file) ? ts.ScriptKind.JS : ts.ScriptKind.TS;
  const source = ts.createSourceFile(file, content, ts.ScriptTarget.Latest, true, kind);
  const groups = { exported: { Types: [], Classes: [], Functions: [], Constants: [], Variables: [] },
    internal: { Types: [], Classes: [], Functions: [], Constants: [], Variables: [] } };
  const reexports = [];
  let defaultExport = null;
  const add = (exported, group, name) => groups[exported ? 'exported' : 'internal'][group].push(name);
  for (const statement of topLevelStatements(source.statements)) {
    const exported = hasExport(statement);
    if (ts.isFunctionDeclaration(statement) && statement.name) add(exported, 'Functions', statement.name.text);
    else if (ts.isClassDeclaration(statement) && statement.name) add(exported, 'Classes', statement.name.text);
    else if (ts.isInterfaceDeclaration(statement) || ts.isTypeAliasDeclaration(statement) || ts.isEnumDeclaration(statement)) {
      add(exported, 'Types', statement.name.text);
    } else if (ts.isVariableStatement(statement)) {
      const constant = (statement.declarationList.flags & ts.NodeFlags.Const) !== 0;
      for (const declaration of statement.declarationList.declarations) {
        if (!ts.isIdentifier(declaration.name)) continue;
        const group = isFunctionLike(declaration.initializer) ? 'Functions' : constant ? 'Constants' : 'Variables';
        add(exported, group, declaration.name.text);
      }
    } else if (ts.isExportDeclaration(statement)) {
      if (statement.exportClause && ts.isNamedExports(statement.exportClause)) {
        reexports.push(...statement.exportClause.elements.map(element => element.name.text));
      } else if (statement.moduleSpecifier) {
        reexports.push(`* from ${statement.moduleSpecifier.getText(source)}`);
      }
    } else if (ts.isExportAssignment(statement)) {
      defaultExport = statement.expression.getText(source).split('\n')[0].slice(0, 60);
    }
  }
  const lines = [];
  for (const [visibility, title] of [['exported', 'Exports'], ['internal', 'Internal']]) {
    const entries = Object.entries(groups[visibility]).filter(([, names]) => names.length);
    if (visibility === 'exported' && (reexports.length || defaultExport)) entries.push(['Re-exports', reexports]);
    if (!entries.length && !(visibility === 'exported' && defaultExport)) continue;
    lines.push(title);
    for (const [group, names] of entries) lines.push(...wrapList(group, unique(names), '  '));
    if (visibility === 'exported' && defaultExport) lines.push(`  Default: ${defaultExport}`);
  }
  const tests = collectTests(source.statements, source);
  if (tests.length) lines.push('Tests', ...tests.map(test => `  ${test}`));
  return lines;
};

/** Lists the class names a stylesheet defines, its custom properties, keyframes, and breakpoints. */
const cssCatalog = content => {
  const stripped = content.replace(/\/\*[\s\S]*?\*\//g, '');
  const classes = [];
  const properties = [];
  const keyframes = [];
  const media = [];
  for (const match of stripped.matchAll(/([^{};]+)\{/g)) {
    const prelude = match[1].trim();
    if (prelude.startsWith('@media')) media.push(prelude.slice(6).trim());
    else if (prelude.startsWith('@keyframes')) keyframes.push(prelude.slice(10).trim());
    else if (!prelude.startsWith('@')) {
      for (const name of prelude.matchAll(/\.(-?[_a-zA-Z][\w-]*)/g)) classes.push(`.${name[1]}`);
    }
  }
  for (const match of stripped.matchAll(/(?:^|[;{\s])(--[\w-]+)\s*:/g)) properties.push(match[1]);
  return [
    ...wrapList('Classes', unique(classes)),
    ...wrapList('Custom properties', unique(properties)),
    ...wrapList('Keyframes', unique(keyframes)),
    ...wrapList('Media queries', unique(media), '', ';')
  ];
};

const shellCatalog = content => wrapList('Functions',
  unique([...content.matchAll(/^(?:function\s+)?([A-Za-z_][\w]*)\s*\(\)\s*\{/gm)].map(match => match[1])));

const pythonCatalog = content => [
  ...wrapList('Classes', unique([...content.matchAll(/^class\s+(\w+)/gm)].map(match => match[1]))),
  ...wrapList('Functions', unique([...content.matchAll(/^def\s+(\w+)/gm)].map(match => match[1])))
];

/** Lists the top-level keys of a YAML document and, for workflows, each job. */
const yamlCatalog = content => {
  const topLevel = [...content.matchAll(/^([A-Za-z_][\w-]*):/gm)].map(match => match[1]);
  const lines = wrapList('Sections', unique(topLevel));
  const jobs = /^jobs:\s*$([\s\S]*)/m.exec(content);
  if (jobs) lines.push(...wrapList('Jobs', [...jobs[1].matchAll(/^  ([A-Za-z_][\w-]*):\s*$/gm)].map(match => match[1])));
  return lines;
};

/** Produces GitHub-compatible heading anchors, numbering duplicates the same way GitHub does. */
const anchorFactory = () => {
  const seen = new Map();
  return heading => {
    const base = heading.trim().toLowerCase()
      .replace(/<[^>]+>/g, '')
      .replace(/[^\p{L}\p{N}\s_-]/gu, '')
      .replace(/\s/g, '-');
    const count = seen.get(base) ?? 0;
    seen.set(base, count + 1);
    return count ? `${base}-${count}` : base;
  };
};

/** Splits a Markdown document into lines, reporting whether each line sits inside a fenced block. */
const markdownLines = content => {
  let fence = null;
  return content.split('\n').map(line => {
    const marker = /^\s*(`{3,}|~{3,})/.exec(line);
    const inFence = fence !== null;
    if (marker && (fence === null || marker[1][0] === fence[0] && marker[1].length >= fence.length)) {
      fence = fence === null ? marker[1] : null;
      return { line, inFence: true };
    }
    return { line, inFence };
  });
};

/** Lists second- and third-level headings as a linked contents list. */
const markdownCatalog = content => {
  const anchor = anchorFactory();
  const entries = [];
  for (const { line, inFence } of markdownLines(content)) {
    const heading = !inFence && /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line);
    if (!heading) continue;
    const id = anchor(heading[2]);
    const level = heading[1].length;
    if (level === 2 || level === 3) {
      const label = heading[2].replace(/`/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
      entries.push(`${level === 3 ? '  ' : ''}- [${label}](#${id})`);
    }
  }
  return entries.length ? ['**Contents**', '', ...entries] : [];
};

const catalogLines = (file, syntax, content) => {
  if (syntax === 'code') return codeCatalog(file, content);
  if (syntax === 'css') return cssCatalog(content);
  if (syntax === 'shell') return shellCatalog(content);
  if (syntax === 'python') return pythonCatalog(content);
  if (syntax === 'yaml') return yamlCatalog(content);
  return markdownCatalog(content);
};

/** Removes an existing catalog block (and the blank line that follows it). */
const stripCatalog = (content, syntax) => {
  const { start, end } = markers[syntax];
  const lines = content.split('\n');
  const first = lines.findIndex(line => line === start || line.startsWith(`${start} `));
  if (first === -1) return content;
  const last = lines.indexOf(end, first);
  if (last === -1) throw new Error(`Unterminated catalog block.`);
  const removeTo = lines[last + 1] === '' ? last + 2 : last + 1;
  lines.splice(first, removeTo - first);
  return lines.join('\n');
};

/** Code catalogs go after a shebang (and a shell's strict-mode line); Markdown catalogs go before the first section heading. */
const insertCatalog = (content, syntax, block) => {
  const lines = content.split('\n');
  let index = 0;
  if (syntax === 'markdown') {
    const located = markdownLines(content).findIndex(({ line, inFence }) => !inFence && /^#{2,6}\s/.test(line));
    index = located === -1 ? lines.length : located;
    return [...lines.slice(0, index), ...block, '', ...lines.slice(index)].join('\n');
  }
  if (lines[0]?.startsWith('#!')) index = 1;
  // Shell strict mode stays the first command after the shebang.
  if (syntax === 'shell' && lines[index]?.startsWith('set -')) index += lines[index + 1] === '' ? 2 : 1;
  return [...lines.slice(0, index), ...block, ...lines.slice(index)].join('\n');
};

const renderBlock = (syntax, lines) => {
  const { start, end, line } = markers[syntax];
  const header = syntax === 'markdown'
    ? start
    : `${start} — generated by \`${generatorCommand}\`; do not edit by hand.`;
  return [header, ...lines.map(line), end, ...(syntax === 'markdown' ? [] : [''])];
};

/** Returns the file content with an up-to-date catalog, or without one when the file is short. */
export const catalogFile = (file, content) => {
  const syntax = syntaxFor(file);
  const bare = stripCatalog(content, syntax);
  if (bare.split('\n').length <= lineThreshold) return { content: bare, empty: false };
  const lines = catalogLines(file, syntax, bare);
  if (!lines.length) return { content: bare, empty: true };
  return { content: insertCatalog(bare, syntax, renderBlock(syntax, lines)), empty: false };
};

const candidateFiles = () => execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard'],
  { cwd: repositoryRoot, encoding: 'utf8' }).split('\n')
  .filter(file => file && syntaxFor(file) && !excluded.some(pattern => pattern.test(file)));

const main = async () => {
  const check = process.argv.includes('--check');
  const stale = [];
  const empty = [];
  for (const file of candidateFiles()) {
    const absolute = path.join(repositoryRoot, file);
    let content;
    try { content = await readFile(absolute, 'utf8'); } catch (error) { if (error.code === 'ENOENT') continue; throw error; }
    const result = catalogFile(file, content);
    if (result.empty) empty.push(file);
    if (result.content === content) continue;
    stale.push(file);
    if (!check) await writeFile(absolute, result.content);
  }
  for (const file of empty) console.warn(`No catalog entries could be derived for ${file}.`);
  if (check && stale.length) {
    console.error(`Stale or missing file catalogs (run \`${generatorCommand}\`):\n${stale.map(file => `  ${file}`).join('\n')}`);
    process.exitCode = 1;
    return;
  }
  console.log(check ? 'File catalogs are current.' : `Updated ${stale.length} file catalogs.`);
};

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
